import {readdir,readFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import assert from 'node:assert/strict';
import {readStoredStandardZip} from '../../apps/api/tests/studio/stored-zip.ts';
const root=resolve('/Users/dingshinn/.codex/worktrees/step-07-review-round9/rpg-maker-maker/.local/step07-review/evidence');
const rows:any[]=[];
for(const mode of ['production','dev'])for(const label of ['first','second','history']){
 const base=resolve(root,'archives',mode,label+'-export.zip');
 const normal=await readFile(base);assert.equal(Object.keys(readStoredStandardZip(normal)).length,8);rows.push({mode,label,case:'normal',accepted:true});
 for(const kind of ['central-crc','eocd-count','local-crc']){
  const bad=await readFile(resolve(root,'archive-negative',mode,label+'-'+kind+'.zip'));
  assert.throws(()=>readStoredStandardZip(bad),/Standard ZIP:/);rows.push({mode,label,case:kind,accepted:false});
 }
}
console.log(JSON.stringify({source:'50fd6d84197b8c6d222f139a142ab24c918db0db',controls:24,normalAccepted:6,badRejected:18,rows},null,2));
